import{z as t,x as p,o as i,c as B,q as n,j as E,D as d,d as a,s,S as r,b as o}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"打开文件表","description":"","frontmatter":{"title":"打开文件表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/file-table.md","filePath":"cs/file-table.md","lastUpdated":1791063341000}'),f={name:"cs/file-table.md"};function c(A,e,m,h,u,D){const l=p("Mermaid");return i(),B("div",null,[e[2]||(e[2]=n('<h1 id="打开文件表" tabindex="-1">打开文件表 <a class="header-anchor" href="#打开文件表" aria-label="Permalink to &quot;打开文件表&quot;">​</a></h1><div class="epigraph"><p>描述符是进程里的整数下标；它指向系统打开文件表的一项，那里才记着偏移与指向 inode 的指针。</p><footer>—— 据 Bach, The Design of the UNIX Operating System；Ritchie and Thompson 的整理</footer></div><p><a href="/cs/file-bytestream">上一课</a>把文件定义为字节流，并点到「偏移在打开文件对象上」。缺口是把这句话收成<strong>三层表</strong>：进程描述符表、系统打开文件表、inode（下一课才展开）。<code>dup</code>、<code>fork</code>、<code>close</code> 的语义全由「谁指向谁」决定，而不是再解释 <code>read</code> 拷贝字节。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若偏移存在 inode 上，两个独立 <code>open</code> 会互相移动对方的读写位置。若偏移只存在描述符上，<code>dup</code> 得到的两个整数又应对同一偏移。Unix 折中：描述符表项是指针；打开文件对象（file）持有偏移与状态；多个描述符可指向同一 file；多个 file 可指向同一 inode。缺口不是磁盘格式，而是这张引用图。</p><p>本课不把 <code>O_CLOEXEC</code> 的每一位旗标写完。</p><p><span class="marginnote">fork 复制描述符表，于是父子共享同一批打开文件对象与偏移。exec 可关闭 CLOEXEC 的那些。close 减引用，到零才释放 file。</span></p><p><span class="marginnote">「打开文件对象」（file）就是「内核记着这个打开实例读到哪了」的小本本：偏移和打开旗标都记在它身上，不在 fd 整数上，也不在 inode 里。fd 只是进程私有数组的下标，翻译过来就是「第几号小本本的钥匙」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>open</code>：分配 file，偏移清零，在进程表里找最小空闲整数当 fd。<code>dup</code>：新槽指向同一 file。<code>lseek</code> 改 file 的偏移。独立 <code>open</code> 两次同一路径：两个 file，两个偏移。<a href="/cs/syscall-path">系统调用路径</a>上 <code>read(fd)</code> 只解第一层下标，越界则 EBADF。引用计数保护并发 close。</p><p><span class="marginnote">数字实例：进程连续 open 三次得到 fd 0、1、2，close 掉 1 号之后，下一次 open 通常拿回最小空闲整数 1。若对只开了 0-2 号的进程执行 <code>read(99)</code>，内核查 99 号槽为空，直接返回 EBADF——错误在解下标这一层就发生，还没碰到 file。</span></p>',11)),(i(),E(r,null,{default:d(()=>[s(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FD%5B%22%E8%BF%9B%E7%A8%8B%20fd%20%E8%A1%A8%22%5D%20--%3E%20FILE%5B%22%E6%89%93%E5%BC%80%E6%96%87%E4%BB%B6%3A%20%E5%81%8F%E7%A7%BB%22%5D%0A%20%20FILE%20--%3E%20INO%5B%22inode%3A%20%E5%90%8E%E8%AF%BE%22%5D%0A%20%20DUP%5B%22dup%22%5D%20--%3E%20FILE%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o("h2",{id:"机制",tabindex:"-1"},[a("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=o("p",null,[a("三层表让管道、套接字、普通文件共用 fd 空间：file 上的操作向量可以不同，用户只看见整数。这与虚存的 fd 无关——mmap 也抓住同一 file/inode。不要把表写成数据库的连接池；它是进程映像的一部分，随"),o("a",{href:"/cs/process-image"},"进程"),a("复制与退出回收。")],-1)),e[5]||(e[5]=o("p",null,"回收器/shrinker 不收缩「打开着的」file；那是引用计数对象。",-1)),(i(),E(r,null,{default:d(()=>[s(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20DUP%5B%22dup(fd)%20%E5%BE%97%E6%96%B0%E6%95%B4%E6%95%B0%22%5D%20--%3E%20S1%5B%22%E4%B8%A4%E4%B8%AA%20fd%20%E6%8C%87%E5%90%91%E5%90%8C%E4%B8%80%20file%3A%20%E5%85%B1%E4%BA%AB%E5%81%8F%E7%A7%BB%22%5D%0A%20%20FORK%5B%22fork%20%E5%A4%8D%E5%88%B6%20fd%20%E8%A1%A8%22%5D%20--%3E%20S2%5B%22%E7%88%B6%E5%AD%90%E5%90%8C%E5%8F%B7%20fd%20%E6%8C%87%E5%90%91%E5%90%8C%E4%B8%80%20file%3A%20%E5%85%B1%E4%BA%AB%E5%81%8F%E7%A7%BB%22%5D%0A%20%20OPEN2%5B%22%E4%B8%A4%E6%AC%A1%E7%8B%AC%E7%AB%8B%20open%20%E5%90%8C%E4%B8%80%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20S3%5B%22%E4%B8%A4%E4%B8%AA%20file%3A%20%E5%90%84%E8%87%AA%E5%81%8F%E7%A7%BB%E4%BA%92%E4%B8%8D%E5%BD%B1%E5%93%8D%22%5D%0A%20%20S1%20--%3E%20INO%5B%22%E6%9C%80%E7%BB%88%E9%83%BD%E8%90%BD%E5%88%B0%E5%90%8C%E4%B8%80%20inode%22%5D%0A%20%20S2%20--%3E%20INO%0A%20%20S3%20--%3E%20INO%0A"})]),fallback:d(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=n('<p><span class="marginnote">常见误区：初学者以为「同一个文件」就共享偏移。实际共享看「打开实例」：两次独立 open 同一路径得到两个 file、两套偏移，各自读写互不干扰；只有 dup 和 fork 得到的描述符才真正共用同一个偏移。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 POSIX 的 <code>dup3</code> 全部细节。不把 Windows HANDLE 表当对照考纲。inode 与目录内容下一课才是持久结构；本课允许说「file 指向一个编号对象」。路径如何变成该对象，再下一课查找。</p><p>后课默认：fd 与偏移的共享规则已定。名字查找的缓存，下一课 dentry。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>fd → 打开文件（偏移）→ inode；dup 共享偏移，两次 open 不共享。</li><li>fork 复制 fd 表，共享打开实例。</li><li>名字到对象的缓存是 dcache 的缺口。</li><li>出处：Bach, <em>UNIX</em>；Ritchie and Thompson, 1974；Tanenbaum <em>MOS</em>。</li></ul>',6))])}const C=t(f,[["render",c]]);export{b as __pageData,C as default};
